                    || (value.mObjType == typeof(int)))
                {
                    ValueInt = value;
                }
                else if (value.mObjType == typeof(double))
                {
                    ValueDouble = value;
                }
                else if (value.mObjType == typeof(bool))
                {
                    ValueBool = value;
                }
                else
                {
                    if (Interface == "IBoolean")
                    {
                        if((string)value == "True")
                        {
                            value = "1";
                        }
                        if ((string)value == "False")
                        {
                            value = "0";
                        }
                    }
                    ValueString = value;
                }
